{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Verapamil, a structurally related dimethoxyphenyl tertiary amine with extensive first-pass metabolism, showed 52.3% absolute oral bioavailability in cirrhotic patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, had 30% absolute oral bioavailability in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Valbenazine, which contains a dimethoxytetrahydroisoquinoline core, had approximately 49% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Colchicine, a trimethoxy-containing alkaloid, had a mean absolute oral bioavailability of 55% in elderly subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Clomipramine, a tricyclic tertiary amine, had approximately 50% oral bioavailability in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Donepezil, a dimethoxy-substituted drug with a basic amine, has approximately 100% oral bioavailability, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Alfuzosin, a dimethoxy-substituted basic drug, had 64.5% absolute oral bioavailability in healthy subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple structurally related analogues with high transfer scores consistently show absolute oral bioavailability above 20% (verapamil 52%, noscapine 30%, valbenazine 49%, colchicine 45-55%, clomipramine 50%, donepezil ~100%, alfuzosin 64%). The only sub-20% value is S-verapamil under rifampin co-treatment, which is not applicable to the query. The physicochemical prior is mixed, but the strong experimental evidence supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "The query's low neutral fraction and potential first-pass metabolism are not experimentally characterized.",
    "No data on transporter-mediated efflux or intestinal metabolism for the query.",
    "Extrapolation relies on structural analogues rather than the exact query compound."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

